begin;
select no_plan();
select ok(not has_function_privilege('anon','public.cancel_unpaid_order(uuid,boolean)','EXECUTE'),'anonymous cannot cancel');
select ok(not has_function_privilege('authenticated','public.reserve_test_payment(uuid,uuid,text)','EXECUTE'),'customer cannot reserve as another actor');
select ok(not has_function_privilege('authenticated','public.attach_test_gateway_order(uuid,text,bigint)','EXECUTE'),'customer cannot attach provider IDs');
select ok(not has_function_privilege('authenticated','public.record_test_capture(uuid,text,text,bigint,text)','EXECUTE'),'customer cannot spoof verification');
select ok(not has_table_privilege('authenticated','public.order_payment_attempts','INSERT'),'no direct attempt inserts');
select ok(not has_table_privilege('authenticated','public.order_payment_attempts','UPDATE'),'no direct attempt updates');
select ok(not has_table_privilege('anon','public.order_payment_attempts','SELECT'),'anonymous payment data hidden');
select ok((select relrowsecurity from pg_class where oid='public.order_payment_attempts'::regclass),'payment RLS enabled');
insert into auth.users(id,email) values ('fd000000-0000-4000-8000-000000000001','payment-customer@faden.local'),('fd000000-0000-4000-8000-000000000002','payment-owner@faden.local'),('fd000000-0000-4000-8000-000000000003','payment-other@faden.local');
insert into public.boutiques(id,owner_id,name,slug,status,is_published) values('fd000000-0000-4000-8000-000000000004','fd000000-0000-4000-8000-000000000002','Payment fixture','payment-fixture','verified',true);
do $$ declare i integer; req uuid; sh uuid; ofr uuid; ord uuid; q jsonb; begin
for i in 1..3 loop
 req=('fd000000-0000-4000-8000-'||lpad((10+i)::text,12,'0'))::uuid;
 sh=('fd000000-0000-4000-8000-'||lpad((20+i)::text,12,'0'))::uuid;
 ofr=('fd000000-0000-4000-8000-'||lpad((30+i)::text,12,'0'))::uuid;
 ord=('fd000000-0000-4000-8000-'||lpad((40+i)::text,12,'0'))::uuid;
 q=jsonb_build_object('title','Payment fixture','items',jsonb_build_array(jsonb_build_object('label','Silk','detail','Fixture','quantity',1,'unit_paise',10000)),'tax_bps',0,'advance_paise',5000,'delivery_date',(current_date+40)::text,'expires_on',(current_date+7)::text,'terms','Fixture terms');
 insert into public.outfit_requests(id,user_id,status,draft) values(req,'fd000000-0000-4000-8000-000000000001','submitted','{}');
 insert into public.request_shares(id,request_id,customer_id,boutique_id,client_label,brief) values(sh,req,'fd000000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000004','Fixture','{}');
 insert into public.boutique_offers(id,share_id,request_id,customer_id,boutique_id,quote,subtotal_paise,tax_paise,total_paise,status,sent_at) values(ofr,sh,req,'fd000000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000004',q,10000,0,10000,'accepted',now());
 insert into public.customer_orders(id,request_id,offer_id,share_id,customer_id,boutique_id,boutique_owner_id,boutique_name,quote,subtotal_paise,tax_paise,total_paise,advance_paise,accepted_offer_version) values(ord,req,ofr,sh,'fd000000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000004','fd000000-0000-4000-8000-000000000002','Payment fixture',q,10000,0,10000,5000,1);
end loop;end; $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"fd000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.cancel_unpaid_order('fd000000-0000-4000-8000-000000000041',true)$$,'P0001',null,'another customer cannot cancel');
select set_config('request.jwt.claims','{"sub":"fd000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.cancel_unpaid_order('fd000000-0000-4000-8000-000000000041',false)$$,'P0001',null,'cancellation requires explicit consent');
select lives_ok($$select public.cancel_unpaid_order('fd000000-0000-4000-8000-000000000041',true)$$,'unstarted unpaid order cancels');
select lives_ok($$select public.cancel_unpaid_order('fd000000-0000-4000-8000-000000000041',true)$$,'cancellation retry idempotent');
select is((select status from public.customer_orders where id='fd000000-0000-4000-8000-000000000041'),'cancelled','cancellation persists');
reset role;
select is((select count(*)::int from public.outbox_events where aggregate_id='fd000000-0000-4000-8000-000000000041' and event_type='order.cancelled'),1,'one cancellation event');
select throws_ok($$select public.reserve_test_payment('fd000000-0000-4000-8000-000000000041','fd000000-0000-4000-8000-000000000001','rzp_test_fixture')$$,'P0001',null,'cancelled order cannot start checkout');
select throws_ok($$select public.reserve_test_payment('fd000000-0000-4000-8000-000000000042','fd000000-0000-4000-8000-000000000001','rzp_live_fixture')$$,'P0001',null,'live keys rejected at DB boundary');
select throws_ok($$select public.reserve_test_payment('fd000000-0000-4000-8000-000000000042','fd000000-0000-4000-8000-000000000003','rzp_test_fixture')$$,'P0001',null,'actor must own the order');
select set_config('test.attempt',public.reserve_test_payment('fd000000-0000-4000-8000-000000000042','fd000000-0000-4000-8000-000000000001','rzp_test_fixture')->>'id',true);
select is(public.reserve_test_payment('fd000000-0000-4000-8000-000000000042','fd000000-0000-4000-8000-000000000001','rzp_test_fixture')->>'is_new','false','reservation retry does not create another remote attempt');
select is((select amount_paise from public.order_payment_attempts where id=current_setting('test.attempt')::uuid),5000::bigint,'advance copied from immutable order');
select throws_ok($$select public.reserve_test_payment('fd000000-0000-4000-8000-000000000042','fd000000-0000-4000-8000-000000000001','rzp_test_rotated')$$,'P0001',null,'key rotation cannot silently replace attempt');
set local role authenticated;
select throws_ok($$select public.cancel_unpaid_order('fd000000-0000-4000-8000-000000000042',true)$$,'P0001',null,'creating attempt prevents unsafe cancellation');
select is((select count(*)::int from public.order_payment_attempts where id=current_setting('test.attempt')::uuid),1,'customer sees own payment');
select set_config('request.jwt.claims','{"sub":"fd000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*)::int from public.order_payment_attempts where id=current_setting('test.attempt')::uuid),0,'other user cannot read payment');
reset role;
select throws_ok($$select public.attach_test_gateway_order(current_setting('test.attempt')::uuid,'order_fixture',1)$$,'P0001',null,'gateway amount mismatch rejected');
select lives_ok($$select public.attach_test_gateway_order(current_setting('test.attempt')::uuid,'order_fixture',5000)$$,'matching provider order attached');
select lives_ok($$select public.attach_test_gateway_order(current_setting('test.attempt')::uuid,'order_fixture',5000)$$,'provider attachment retry idempotent');
select throws_ok($$select public.attach_test_gateway_order(current_setting('test.attempt')::uuid,'order_other',5000)$$,'P0001',null,'provider order cannot be replaced');
select throws_ok($$select public.record_test_capture(current_setting('test.attempt')::uuid,'order_other','pay_fixture',5000,'INR')$$,'P0001',null,'mismatched order capture rejected');
select throws_ok($$select public.record_test_capture(current_setting('test.attempt')::uuid,'order_fixture','pay_fixture',5001,'INR')$$,'P0001',null,'mismatched amount capture rejected');
select throws_ok($$select public.record_test_capture(current_setting('test.attempt')::uuid,'order_fixture','pay_fixture',5000,'USD')$$,'P0001',null,'mismatched currency capture rejected');
select lives_ok($$select public.record_test_capture(current_setting('test.attempt')::uuid,'order_fixture','pay_fixture',5000,'INR')$$,'server verified capture recorded');
select lives_ok($$select public.record_test_capture(current_setting('test.attempt')::uuid,'order_fixture','pay_fixture',5000,'INR')$$,'duplicate capture notification idempotent');
select throws_ok($$select public.record_test_capture(current_setting('test.attempt')::uuid,'order_fixture','pay_other',5000,'INR')$$,'P0001',null,'different payment cannot replace receipt');
select is((select status from public.customer_orders where id='fd000000-0000-4000-8000-000000000042'),'test_advance_paid','test status cannot be confused with real paid state');
select is((select count(*)::int from public.outbox_events where aggregate_id='fd000000-0000-4000-8000-000000000042' and event_type='payment.test_captured'),1,'duplicate callbacks produce one capture event');
select throws_ok($$select public.reserve_test_payment('fd000000-0000-4000-8000-000000000042','fd000000-0000-4000-8000-000000000001','rzp_test_fixture')$$,'P0001',null,'captured advance cannot open another checkout');
update public.customer_orders set advance_paise=0 where id='fd000000-0000-4000-8000-000000000043';
select throws_ok($$select public.reserve_test_payment('fd000000-0000-4000-8000-000000000043','fd000000-0000-4000-8000-000000000001','rzp_test_fixture')$$,'P0001',null,'zero advance does not imply payment');
select * from finish();
rollback;
